def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Improved version of `equation_v0` with quadratic terms for both gate_voltage_abs and drain_voltage_abs."""
    return parameters[0] + parameters[1] * gate_voltage_abs + parameters[2] * drain_voltage_abs + parameters[3] * np.square(gate_voltage_abs) + parameters[4] * np.square(drain_voltage_abs)
